__global__ void tall_skinny_matmul_kernel(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Block and thread indices
    int row_block = blockIdx.y;
    int col_block = blockIdx.x;
    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Global row and column indices
    int row = row_block * blockDim.y + thread_row;
    int col = col_block * blockDim.x + thread_col;

    // Check bounds
    if (row >= M || col >= N) return;

    // Compute dot product for this output element
    float sum = 0.0f;

    // Iterate over K dimension (the small shared dimension)
    for (int k = 0; k < K; k++) {
        float a_val = A[row * K + k];
        float b_val = B[k * N + col];
        sum += a_val * b_val;
    }

    // Store result
    C[row * N + col] = sum;
}

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    // Get dimensions
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    // Create output tensor
    auto C = torch::zeros({M, N}, A.options());

    // Use 16x16 thread blocks for good occupancy
    const int BLOCK_ROWS = 16;
    const int BLOCK_COLS = 16;

    dim3 blockDim(BLOCK_COLS, BLOCK_ROWS);
    dim3 gridDim((N + BLOCK_COLS - 1) / BLOCK_COLS, (M + BLOCK_ROWS - 1) / BLOCK_ROWS);

    tall_skinny_matmul_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        M, K, N);

    return C;
}
