#include <hip/hip_runtime.h>

#define TILE_SIZE_M 16
#define TILE_SIZE_N 16
#define TILE_SIZE_K 16

__global__ void tall_skinny_matmul_kernel_shared(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Block indices
    int by = blockIdx.y;
    int bx = blockIdx.x;

    // Thread indices
    int ty = threadIdx.y;
    int tx = threadIdx.x;

    // Global output indices
    int row = by * TILE_SIZE_M + ty;
    int col = bx * TILE_SIZE_N + tx;

    // Shared memory tiles
    __shared__ float tile_A[TILE_SIZE_M][TILE_SIZE_K];
    __shared__ float tile_B[TILE_SIZE_K][TILE_SIZE_N];

    // Accumulator
    float sum = 0.0f;

    // Iterate over K in tiles
    for (int t = 0; t < K; t += TILE_SIZE_K) {
        // Load tile of A
        for (int k = 0; k < TILE_SIZE_K; k++) {
            int a_row = by * TILE_SIZE_M + ty;
            int a_col = t + k;
            if (a_row < M && a_col < K) {
                tile_A[ty][k] = A[a_row * K + a_col];
            } else {
                tile_A[ty][k] = 0.0f;
            }
        }

        // Load tile of B
        for (int k = 0; k < TILE_SIZE_K; k++) {
            int b_row = t + k;
            int b_col = bx * TILE_SIZE_N + tx;
            if (b_row < K && b_col < N) {
                tile_B[k][tx] = B[b_row * N + b_col];
            } else {
                tile_B[k][tx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial sum for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE_K; k++) {
            sum += tile_A[ty][k] * tile_B[k][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 blockDim(TILE_SIZE_N, TILE_SIZE_M);
    dim3 gridDim((N + TILE_SIZE_N - 1) / TILE_SIZE_N, (M + TILE_SIZE_M - 1) / TILE_SIZE_M);

    tall_skinny_matmul_kernel_shared<<<gridDim, blockDim>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
